public class GradientBandPainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage render(int width, int height,
                                               java.awt.Color left, java.awt.Color right) {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                width, height, java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = img.createGraphics();
        try {
            GradientBandPainter.paint(g, width, height, left, right);
        } finally {
            g.dispose();
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage a = render(100, 60, java.awt.Color.BLACK, java.awt.Color.WHITE);
            java.awt.image.BufferedImage b = render(80, 40, java.awt.Color.BLUE, java.awt.Color.YELLOW);
            check("dark left end of the gradient (5,10)", "#0B0B0B", pixel(a, 5, 10));
            check("middle of the gradient (50,10)", "#7F7F7F", pixel(a, 50, 10));
            check("light right end of the gradient (95,10)", "#F2F2F2", pixel(a, 95, 10));
            check("gradient depends on x only (50,40)", "#7F7F7F", pixel(a, 50, 40));
            check("solid red footer (50,55)", "#FF0000", pixel(a, 50, 55));
            check("footer spans the full width (5,55)", "#FF0000", pixel(a, 5, 55));
            check("blue end of the second gradient (4,5)", "#0B0BF3", pixel(b, 4, 5));
            check("yellow end of the second gradient (76,5)", "#F2F20C", pixel(b, 76, 5));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

