import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;

public class GradientBandPainter {

    public static void paint(Graphics2D g, int width, int height, Color left, Color right) {
        GradientPaint gp = new GradientPaint(0, 0, left, width, 0, right);
        g.setPaint(gp);
        g.fillRect(0, 0, width, height);

        g.setPaint(Color.RED);
        g.fillRect(0, height - 10, width, 10);
    }
}
